using System;
using System.Net;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Api.Models.Auth;
using Api.Services;
using Api.Utilities;
using Domain.Entities;
using Infrastructure.Data;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
using Moq;
using Domain.Interfaces;
using Microsoft.Extensions.Logging;

namespace Api.Tests
{
    public class AuthEndpointsTests : IClassFixture<TestWebApplicationFactory<Program>>
    {
        private readonly TestWebApplicationFactory<Program> _factory;

        public AuthEndpointsTests(TestWebApplicationFactory<Program> factory)
        {
            _factory = factory;
        }

        [Fact]
        public async Task Register_ValidUser_ReturnsOk()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request = new RegisterRequest("testuser", "test@example.com", "Password123!");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request);

            // Assert
            response.EnsureSuccessStatusCode(); // Status Code 200-299
            var authResponse = await response.Content.ReadFromJsonAsync<AuthResponse>();
            Assert.NotNull(authResponse);
            Assert.Equal("testuser", authResponse.Username);
            Assert.NotEmpty(authResponse.Token);
        }

        [Fact]
        public async Task Register_DuplicateUsername_ReturnsBadRequest()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request1 = new RegisterRequest("duplicateuser", "dup1@example.com", "Password123!");
            var request2 = new RegisterRequest("duplicateuser", "dup2@example.com", "Password123!");

            await client.PostAsJsonAsync("/v1/auth/register", request1); // Register first user

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request2);

            // Assert
            Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Username already exists.", (string)error!.error);
        }

        [Fact]
        public async Task Register_DuplicateEmail_ReturnsBadRequest()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request1 = new RegisterRequest("user1", "duplicate@example.com", "Password123!");
            var request2 = new RegisterRequest("user2", "duplicate@example.com", "Password123!");

            await client.PostAsJsonAsync("/v1/auth/register", request1); // Register first user

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request2);

            // Assert
            Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Email already exists.", (string)error!.error);
        }

        [Fact]
        public async Task Login_ValidCredentials_ReturnsOk()
        {
            // Arrange
            var client = _factory.CreateClient();
            var registerRequest = new RegisterRequest("loginuser", "login@example.com", "Password123!");
            await client.PostAsJsonAsync("/v1/auth/register", registerRequest);

            var loginRequest = new LoginRequest("loginuser", "Password123!");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.EnsureSuccessStatusCode();
            var authResponse = await response.Content.ReadFromJsonAsync<AuthResponse>();
            Assert.NotNull(authResponse);
            Assert.Equal("loginuser", authResponse.Username);
            Assert.NotEmpty(authResponse.Token);
        }

        [Fact]
        public async Task Login_InvalidCredentials_ReturnsUnauthorized()
        {
            // Arrange
            var client = _factory.CreateClient();
            var loginRequest = new LoginRequest("nonexistent", "wrongpassword");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Invalid username or password.", (string)error!.error);
        }
    }
}
ENDFILE

import { useState, useEffect, useCallback, useMemo } from 'react'; // Added useMemo
import { Todo, CreateTodoPayload, UpdateTodoPayload } from '../types/todo';
import { getTodos, getTodoById, createTodo, updateTodo, deleteTodo } from '../api/todos';

export type FilterStatus = 'all' | 'active' | 'completed';
export type SortBy = 'title' | 'completed';
export type SortOrder = 'asc' | 'desc';

export const useTodos = () => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<FilterStatus>('all');
  const [sortBy, setSortBy] = useState<SortBy>('title');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const fetchTodos = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      let completedFilter: boolean | undefined;
      if (filter === 'active') {
        completedFilter = false;
      } else if (filter === 'completed') {
        completedFilter = true;
      }
      const data = await getTodos(completedFilter);
      setTodos(data);
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const addTodo = useCallback(async (payload: CreateTodoPayload) => {
    try {
      const newTodo = await createTodo(payload);
      setTodos((prev) => [...prev, newTodo]);
      return newTodo;
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
      throw err;
    }
  }, []);

  const updateExistingTodo = useCallback(async (id: string, payload: UpdateTodoPayload) => {
    try {
      // The updateTodo API call returns a Todo, but the current backend PUT returns NoContent.
      // For now, we'll refetch or manually update the state based on payload.
      // Assuming the backend PUT returns the updated todo for simplicity in frontend state management.
      // If backend returns NoContent, a refetch (fetchTodos()) would be more robust.
      await updateTodo(id, payload);
      setTodos((prev) => prev.map((todo) => (todo.id === id ? { ...todo, ...payload } as Todo : todo)));
      // If backend returns the updated todo, use that:
      // const updatedTodo = await updateTodo(id, payload);
      // setTodos((prev) => prev.map((todo) => (todo.id === id ? updatedTodo : todo)));
      // return updatedTodo;
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
      throw err;
    }
  }, []);

  const removeTodo = useCallback(async (id: string) => {
    try {
      await deleteTodo(id);
      setTodos((prev) => prev.filter((todo) => todo.id !== id));
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
      throw err;
    }
  }, []);

  const getTodo = useCallback(async (id: string) => {
    setLoading(true);
    setError(null);
    try {
      const todo = await getTodoById(id);
      return todo;
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const sortedTodos = useMemo(() => { // Memoized sortedTodos
    return [...todos].sort((a, b) => {
      let compare = 0;
      if (sortBy === 'title') {
        compare = a.title.localeCompare(b.title);
      } else if (sortBy === 'completed') {
        compare = (a.completed === b.completed) ? 0 : a.completed ? 1 : -1;
      }
      return sortOrder === 'asc' ? compare : -compare;
    });
  }, [todos, sortBy, sortOrder]);

  return {
    todos: sortedTodos,
    loading,
    error,
    filter,
    setFilter,
    sortBy,
    setSortBy,
    sortOrder,
    setSortOrder,
    addTodo,
    updateTodo: updateExistingTodo,
    removeTodo,
    getTodo,
    fetchTodos,
  };
};
