using Microsoft.EntityFrameworkCore;
using Api.Data;
using Api.Models;
using Api.DTOs;
using Api.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization; // Added for F-001
using Microsoft.AspNetCore.Authentication.JwtBearer; // Added for F-001

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();

// F-001: Add Authentication and Authorization services
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        // This is a placeholder configuration.
        // In a real application, configure JWT options (Authority, Audience, etc.)
        // For simplicity, we're just enabling the scheme.
        options.Authority = builder.Configuration["Jwt:Authority"];
        options.Audience = builder.Configuration["Jwt:Audience"];
        options.RequireHttpsMetadata = builder.Environment.IsProduction();
    });
builder.Services.AddAuthorization();


// Configure PostgreSQL and EF Core
var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ??
                       throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");

builder.Services.AddNpgsql<AppDbContext>(connectionString);
builder.Services.AddScoped<TodoService>();

var app = builder.Build();

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();

    // Apply migrations on startup in development
    using (var scope = app.Services.CreateScope())
    {
        var dbContext = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        dbContext.Database.Migrate();
    }
}

app.UseHttpsRedirection();

// F-001: Enable Authentication and Authorization middleware
app.UseAuthentication();
app.UseAuthorization();

// Define API Endpoints
app.MapGet("/v1/todos", [Authorize] async (TodoService todoService) => // F-001: Added [Authorize]
{
    var todos = await todoService.GetAllTodosAsync();
    // F-003: Centralized DTO mapping
    return Results.Ok(todos.Select(t => t.ToTodoResponse()));
})
.WithName("GetAllTodos")
.Produces<IEnumerable<TodoResponse>>(StatusCodes.Status200OK);

app.MapPost("/v1/todos", [Authorize] async (CreateTodoRequest request, TodoService todoService) => // F-001: Added [Authorize]
{
    // F-004: Removed redundant title validation, relying on DTO attributes
    // if (string.IsNullOrWhiteSpace(request.Title))
    // {
    //     return Results.BadRequest(new { message = "Title is required." });
    // }

    var todo = await todoService.CreateTodoAsync(request.Title);
    // F-003: Centralized DTO mapping
    return Results.Created($"/v1/todos/{todo.Id}", todo.ToTodoResponse());
})
.WithName("CreateTodo")
.Produces<TodoResponse>(StatusCodes.Status201Created)
.Produces(StatusCodes.Status400BadRequest);

app.MapPut("/v1/todos/{id}/complete", [Authorize] async (Guid id, TodoService todoService) => // F-001: Added [Authorize]
{
    var result = await todoService.MarkTodoAsCompleteAsync(id);
    return result.Match(
        // F-003: Centralized DTO mapping
        todo => Results.Ok(todo.ToTodoResponse()),
        error => error switch
        {
            NotFoundError => Results.NotFound(new { message = error.Message }),
            _ => Results.StatusCode(StatusCodes.Status500InternalServerError, new { message = "An unexpected error occurred." })
        }
    );
})
.WithName("CompleteTodo")
.Produces<TodoResponse>(StatusCodes.Status200OK)
.Produces(StatusCodes.Status404NotFound)
.Produces(StatusCodes.Status500InternalServerError);

app.MapDelete("/v1/todos/{id}", [Authorize] async (Guid id, TodoService todoService) => // F-001: Added [Authorize]
{
    var result = await todoService.DeleteTodoAsync(id);
    return result.Match(
        _ => Results.NoContent(),
        error => error switch
        {
            NotFoundError => Results.NotFound(new { message = error.Message }),
            _ => Results.StatusCode(StatusCodes.Status500InternalServerError, new { message = "An unexpected error occurred." })
        }
    );
})
.WithName("DeleteTodo")
.Produces(StatusCodes.Status204NoContent)
.Produces(StatusCodes.Status404NotFound)
.Produces(StatusCodes.Status500InternalServerError);

app.Run();

// F-007: For production, remove automatic migrations and manage them via CI/CD pipeline.
// Keep for development if desired.

