using Microsoft.EntityFrameworkCore;
using Api.Data;
using Api.Models;
using Api.DTOs;
using Api.Services;
using Api.Results;
using Microsoft.AspNetCore.Diagnostics; // Added for IExceptionHandlerPathFeature
using Microsoft.AspNetCore.Authentication.JwtBearer; // Added for JWT
using Microsoft.AspNetCore.Authorization; // Added for Authorize attribute
using Microsoft.IdentityModel.Tokens; // Added for SymmetricSecurityKey
using System.Text; // Added for Encoding

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();

// Configure logging
builder.Services.AddLogging(config =>
{
    config.AddConsole();
    config.AddDebug();
});

// Configure PostgreSQL DbContext
builder.Services.AddDbContextFactory<AppDbContext>(options =>
    options.UseNpgsql(builder.Configuration.GetConnectionString("DefaultConnection")));

// Register TodoService
builder.Services.AddScoped<ITodoService, TodoService>();

// Configure JWT Authentication
var jwtSecret = builder.Configuration["Jwt:Key"] ?? throw new InvalidOperationException("JWT Secret Key not configured.");
builder.Services.AddAuthentication(options =>
{
    options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
})
.AddJwtBearer(options =>
{
    options.TokenValidationParameters = new TokenValidationParameters
    {
        ValidateIssuer = true,
        ValidateAudience = true,
        ValidateLifetime = true,
        ValidateIssuerSigningKey = true,
