import { useState, useEffect, useCallback } from 'react';
import { Todo, CreateTodoPayload, UpdateTodoPayload } from '../types/todo';
import { getTodos, getTodoById, createTodo, updateTodo, deleteTodo } from '../api/todos';

export type FilterStatus = 'all' | 'active' | 'completed';
export type SortBy = 'title' | 'completed';
export type SortOrder = 'asc' | 'desc';

export const useTodos = () => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<FilterStatus>('all');
  const [sortBy, setSortBy] = useState<SortBy>('title');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const fetchTodos = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      let completedFilter: boolean | undefined;
      if (filter === 'active') {
        completedFilter = false;
      } else if (filter === 'completed') {
        completedFilter = true;
      }
      const data = await getTodos(completedFilter);
      setTodos(data);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const addTodo = useCallback(async (payload: CreateTodoPayload) => {
    try {
      const newTodo = await createTodo(payload);
      setTodos((prev) => [...prev, newTodo]);
      return newTodo;
    } catch (err: any) {
      setError(err.message);
      throw err;
    }
  }, []);

  const updateExistingTodo = useCallback(async (id: string, payload: UpdateTodoPayload) => {
    try {
      const updatedTodo = await updateTodo(id, payload);
      setTodos((prev) => prev.map((todo) => (todo.id === id ? updatedTodo : todo)));
      return updatedTodo;
    } catch (err: any) {
      setError(err.message);
      throw err;
    }
  }, []);

  const removeTodo = useCallback(async (id: string) => {
    try {
      await deleteTodo(id);
      setTodos((prev) => prev.filter((todo) => todo.id !== id));
    } catch (err: any) {
      setError(err.message);
      throw err;
    }
  }, []);

  const getTodo = useCallback(async (id: string) => {
    setLoading(true);
    setError(null);
    try {
      const todo = await getTodoById(id);
      return todo;
    } catch (err: any) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const sortedTodos = [...todos].sort((a, b) => {
    let compare = 0;
    if (sortBy === 'title') {
      compare = a.title.localeCompare(b.title);
    } else if (sortBy === 'completed') {
      compare = (a.completed === b.completed) ? 0 : a.completed ? 1 : -1;
    }
    return sortOrder === 'asc' ? compare : -compare;
  });

  return {
    todos: sortedTodos,
    loading,
    error,
    filter,
    setFilter,
    sortBy,
    setSortBy,
    sortOrder,
    setSortOrder,
    addTodo,
    updateTodo: updateExistingTodo,
    removeTodo,
    getTodo,
    fetchTodos,
  };
};
ENDFILE

import React from 'react';
import { render, screen, waitFor, fireEvent } from '@testing-library/react';
import HomePage from './HomePage';
import * as todoApi from '../api/todos';
import { Todo } from '../types/todo';

// Mock the API calls
jest.mock('../api/todos', () => ({
  getTodos: jest.fn(),
  createTodo: jest.fn(),
  toggleTodoComplete: jest.fn(),
  deleteTodo: jest.fn(),
}));

const mockTodos: Todo[] = [
  { id: '1', title: 'Learn React', completed: false },
  { id: '2', title: 'Build a Todo App', completed: true },
];

describe('HomePage', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    (todoApi.getTodos as jest.Mock).mockResolvedValue(mockTodos);
    (todoApi.createTodo as jest.Mock).mockImplementation((title: string) =>
      Promise.resolve({ id: Date.now().toString(), title, completed: false })
    );
    (todoApi.toggleTodoComplete as jest.Mock).mockImplementation((id: string, completed: boolean) =>
      Promise.resolve({ id, title: `Todo ${id}`, completed })
    );
    (todoApi.deleteTodo as jest.Mock).mockResolvedValue(undefined);
  });

  test('renders loading state initially', () => {
    (todoApi.getTodos as jest.Mock).mockReturnValueOnce(new Promise(() => {})); // Never resolve
    render(<HomePage />);
    expect(screen.getByText('Loading todos...')).toBeInTheDocument();
  });

  test('renders todos after fetching', async () => {
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText('Learn React')).toBeInTheDocument());
    expect(screen.getByText('Build a Todo App')).toBeInTheDocument();
    expect(screen.getAllByRole('checkbox')).toHaveLength(2);
  });

  test('handles error when fetching todos', async () => {
    (todoApi.getTodos as jest.Mock).mockRejectedValueOnce(new Error('Network error'));
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText(/Error: Failed to fetch todos/i)).toBeInTheDocument());
  });

  test('adds a new todo', async () => {
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText('Learn React')).toBeInTheDocument());

    const inputElement = screen.getByPlaceholderText('Add a new todo');
    const addButton = screen.getByRole('button', { name: /add todo/i });

    fireEvent.change(inputElement, { target: { value: 'New Todo Item' } });
    fireEvent.click(addButton);

    await waitFor(() => expect(todoApi.createTodo).toHaveBeenCalledWith('New Todo Item'));
    await waitFor(() => expect(screen.getByText('New Todo Item')).toBeInTheDocument());
  });

  test('toggles todo completion', async () => {
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText('Learn React')).toBeInTheDocument());

    const learnReactCheckbox = screen.getAllByRole('checkbox')[0]; // 'Learn React' is the first todo
    expect(learnReactCheckbox).not.toBeChecked();

    fireEvent.click(learnReactCheckbox);

    await waitFor(() => expect(todoApi.toggleTodoComplete).toHaveBeenCalledWith('1', true));
    await waitFor(() => expect(learnReactCheckbox).toBeChecked());
  });

  test('deletes a todo', async () => {
    render(<HomePage />);
    await waitFor(() => expect(screen.getByText('Learn React')).toBeInTheDocument());

    const deleteButtons = screen.getAllByRole('button', { name: /delete/i });
    fireEvent.click(deleteButtons[0]); // Delete 'Learn React'

    await waitFor(() => expect(todoApi.deleteTodo).toHaveBeenCalledWith('1'));
    await waitFor(() => expect(screen.queryByText('Learn React')).not.toBeInTheDocument());
    expect(screen.getByText('Build a Todo App')).toBeInTheDocument();
  });
});
