import { useEffect, useRef, useState, useCallback } from "react";

interface WebSocketOptions {
  onOpen?: (event: Event) => void;
  onMessage?: (event: MessageEvent) => void;
  onError?: (event: Event) => void;
  onClose?: (event: CloseEvent) => void;
  reconnectInterval?: number;
  reconnectLimit?: number;
}

export const useWebSocket = (url: string, options?: WebSocketOptions) => {
  const {
    onOpen,
    onMessage,
    onError,
    onClose,
    reconnectInterval = 3000,
    reconnectLimit = 5,
  } = options || {};

  const ws = useRef<WebSocket | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const reconnectAttempts = useRef(0);
  const timeoutId = useRef<NodeJS.Timeout | null>(null);

  const connect = useCallback(() => {
    if (ws.current && (ws.current.readyState === WebSocket.OPEN || ws.current.readyState === WebSocket.CONNECTING)) {
      return; // Already connected or connecting
    }

    if (reconnectAttempts.current >= reconnectLimit) {
      console.warn("WebSocket reconnect limit reached.");
      return;
    }

    console.log(`Attempting to connect to WebSocket: ${url}`);
    ws.current = new WebSocket(url);

    ws.current.onopen = (event) => {
      console.log("WebSocket connected.");
      setIsConnected(true);
      reconnectAttempts.current = 0;
      onOpen?.(event);
    };

    ws.current.onmessage = (event) => {
      setMessage(event.data);
      onMessage?.(event);
    };

    ws.current.onerror = (event) => {
      console.error("WebSocket error:", event);
      onError?.(event);
    };

    ws.current.onclose = (event) => {
      console.log("WebSocket disconnected:", event.code, event.reason);
      setIsConnected(false);
      onClose?.(event);

      if (!event.wasClean && reconnectAttempts.current < reconnectLimit) {
        reconnectAttempts.current++;
        console.log(`Attempting to reconnect in ${reconnectInterval / 1000}s... (Attempt ${reconnectAttempts.current}/${reconnectLimit})`);
        timeoutId.current = setTimeout(connect, reconnectInterval);
      }
    };
  }, [url, onOpen, onMessage, onError, onClose, reconnectInterval, reconnectLimit]);

  const disconnect = useCallback(() => {
    if (ws.current) {
      ws.current.close();
      if (timeoutId.current) {
        clearTimeout(timeoutId.current);
      }
    }
  }, []);

  useEffect(() => {
    connect();
    return () => {
      disconnect();
    };
  }, [connect, disconnect]);

  const sendMessage = useCallback((message: string) => {
    if (ws.current && ws.current.readyState === WebSocket.OPEN) {
      ws.current.send(message);
    } else {
      console.warn("WebSocket is not open. Cannot send message.");
    }
  }, []);

  return { ws: ws.current, isConnected, message, sendMessage, connect, disconnect };
};
