import { ITodo } from '../types/Todo';

const API_BASE_URL = '/api/v1/todos';

// F-008: Centralized API response handling for better error messages
const handleApiResponse = async (response: Response): Promise<any> => {
  if (response.status === 204) { // No Content
    return null;
  }
  if (!response.ok) {
    const errorBody = await response.json().catch(() => null); // F-008: Try to parse JSON error
    const errorMessage = errorBody?.detail || errorBody?.message || response.statusText;
    throw new Error(`API Error: ${errorMessage}`);
  }
  return response.json();
};

export const getTodos = async (
  completed?: boolean
): Promise<ITodo[]> => {
  const params = new URLSearchParams();
  if (completed !== undefined) {
    params.append('completed', String(completed));
  }
  // F-002: Removed sortBy and sortOrder from params as backend does not utilize them
  const response = await fetch(`${API_BASE_URL}?${params.toString()}`);
  return handleApiResponse(response);
};

export const getTodo = async (id: string): Promise<ITodo> => {
  const response = await fetch(`${API_BASE_URL}/${id}`);
  return handleApiResponse(response);
};

export const createTodo = async (todo: Omit<ITodo, 'id' | 'createdAt' | 'updatedAt'>): Promise<ITodo> => {
  const response = await fetch(API_BASE_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(todo),
  });
  return handleApiResponse(response);
};

export const updateTodo = async (id: string, todo: Partial<Omit<ITodo, 'createdAt' | 'updatedAt'>>): Promise<void> => { // F-005: Changed return type to void
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(todo),
  });
  await handleApiResponse(response); // F-005: No content expected from backend
};

export const deleteTodo = async (id: string): Promise<void> => {
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: 'DELETE',
  });
  await handleApiResponse(response); // F-005: No content expected from backend
};
